mapper.select:
/* selectReqById - Lee MS */
SELECT A.SLFRL_SPRT_TRPR_SE_CD AS SLFRL_SPRT_TRPR_SE_CD, /* 자립지원대상자코드 */ A.RQST_CS_CN AS RQST_CS_CN, /* 의뢰사유내용 */ A.RQST_CS_ETC_CN AS RQST_CS_ETC_CN, /* 의뢰사유기타내용 */ A.RQST_CS_DETAIA_CN AS RQST_CS_DETAIA_CN, /* 지원욕구 세부내용 */ A.ATFINO AS ATFINO, /* 첨부파일번호 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ FROM AEB120 A /* 자립지원사례기본 */ WHERE A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

/* selectCaseJgmtById - Lee MS */
SELECT A.SLFRL_PRPARE_RELM_SE_CD AS SLFRL_PRPARE_RELM_SE_CD, /* 자립준비영역구분코드 */ A.WGHTVA_VALUE AS WGHTVA_VALUE, /* 가중치값 */ B.ADDTNG_MNG_VALUE2 AS PSCORE_SCORE, /* 만점점수 */ A.SLFRL_PRPARE_EVL_SCORE AS SLFRL_PRPARE_EVL_SCORE, /* 자립준비평가점수 */ A.CNVRSN_SCORE AS CNVRSN_SCORE, /* 환산점수 */ A.RISK_LEVEL_SE_CD AS RISK_LEVEL_SE_CD, /* 위험수준구분코드 */ A.RVW_OPNN_CN AS RVW_OPNN_CN, /* 검토의견내용 */
A.STBLT_YN AS STBLT_YN, /* 적합여부 */ A.JGMT_RESULT_SE_CD AS JGMT_RESULT_SE_CD, /* 판정결과구분코드 */ A.EXMN_YMD AS EXMN_YMD, /* 조사일자 */
A.CASE_MNG_NO AS CASE_MNG_NO, /* 사례관리번호 */ A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO /* 사례관리차수 */ FROM AEB110 A, SAC100 B /* 사례판정결과 */ WHERE B.CMMNS_CD_ID = 'SLFRL_PRPARE_RELM_SE_CD' AND A.SLFRL_PRPARE_RELM_SE_CD = B.CMMNS_CD_VALUE AND A.CASE_MNG_NO = #{CASE_MNG_NO} AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}


/* selectSlfrlPrpareById - Lee MS */

SELECT
    A.FCTR_RELM_SE_CD AS FCTR_RELM_SE_CD,               /* 요인영역구분코드 */
    A.FCTR_RELM_AVRG_SCORE AS FCTR_RELM_AVRG_SCORE,     /* 요인영역평균점수 */
    A.FCTR_RELM_CNVRSN_SCORE AS FCTR_RELM_CNVRSN_SCORE, /* 요인영역환산점수 */
    A.INSP_RESULT_CN AS INSP_RESULT_CN,                 /* 검사결과내용 */  
    A.EXMN_YMD AS EXMN_YMD,                             /* 조사일자 */
    A.CASE_MNG_NO AS CASE_MNG_NO,                       /* 사례관리번호 */
    A.CASE_MNG_ODRNO AS CASE_MNG_ODRNO                  /* 사례관리차수 */
FROM AEB140 A    /* 자립지원척도 */
WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
  AND A.CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD}
